const game = new GF.Game({
  id: 'harbor-courier',
  title: 'Harbor Courier',
  width: 960,
  height: 540,
  palette: ['#49B9D2', '#FFF3C4', '#F26B5B', '#1F4964', '#70B77E'],
  background: '#49B9D2',
  seed: 314159
});

/* GF 1.0 exposes telemetry in factory builds; this bridge keeps the same bounded
   evidence channel available in the standalone micro-engine source. */
if (typeof game.event !== 'function') {
  game.event = function (type, data) {
    const item = { type: String(type), data: data || {}, time: this.time };
    if (window.__GF__) {
      if (!Array.isArray(window.__GF__.events)) window.__GF__.events = [];
      if (window.__GF__.events.length < 180) window.__GF__.events.push(item);
    }
    try { window.dispatchEvent(new CustomEvent('gf-event', { detail: item })); } catch (e) {}
  };
}

const C = {
  water: '#49B9D2', cream: '#FFF3C4', coral: '#F26B5B', ink: '#1F4964',
  leaf: '#70B77E', sand: '#F8E7B4', road: '#F4D99A', amber: '#F3AD4E', white: '#FFFDF0'
};

const stops = [
  { name: 'Marina Cafe', color: '#F26B5B', crate: { x: 152, y: 300 }, door: { x: 425, y: 365 }, icon: 'CAFE' },
  { name: 'Lighthouse House', color: '#F3AD4E', crate: { x: 487, y: 416 }, door: { x: 696, y: 222 }, icon: 'HOME' },
  { name: 'Market Pier', color: '#70B77E', crate: { x: 736, y: 395 }, door: { x: 856, y: 176 }, icon: 'MARKET' }
];

const scene = {
  obstacles: [
    { x: 238, y: 246, w: 94, h: 92, type: 'building' },
    { x: 356, y: 72, w: 172, h: 98, type: 'building' },
    { x: 544, y: 288, w: 84, h: 105, type: 'garden' },
    { x: 615, y: 72, w: 118, h: 112, type: 'building' },
    { x: 754, y: 252, w: 80, h: 92, type: 'dock' },
    { x: 75, y: 76, w: 144, h: 92, type: 'building' },
    { x: 348, y: 454, w: 188, h: 45, type: 'garden' }
  ],

  init() {},

  reset() {
    const terminalRestart = !!this.wasTerminal;
    this.x = 105;
    this.y = 300;
    this.vx = 0;
    this.vy = 0;
    this.angle = 0;
    this.stage = 0;
    this.delivered = 0;
    this.carrying = false;
    this.timer = 70;
    this.contacts = 0;
    this.contactLock = 0;
    this.driveSent = false;
    this.assistFuel = 0;
    this.routeIndex = 0;
    this.route = [];
    this.elapsed = 0;
    this.pulse = 0;
    this.note = 'DRIVE TO THE GOLD PARCEL';
    this.noteTime = 0;
    this.warningSecond = 99;
    this.musicTime = 2.5;
    this.wasTerminal = false;
    if (terminalRestart) game.event('fresh_run_started', { timer: 70, deliveries: 0 });
  },

  isSolid(x, y) {
    const r = 12;
    if (x < 47 || x > 913 || y < 66 || y > 500) return true;
    for (let i = 0; i < this.obstacles.length; i++) {
      const o = this.obstacles[i];
      if (x + r > o.x && x - r < o.x + o.w && y + r > o.y && y - r < o.y + o.h) return true;
    }
    return false;
  },

  makeRoute() {
    const s = stops[this.stage];
    if (!s) return [];
    if (!this.carrying) {
      if (this.stage === 0) return [{ x: s.crate.x, y: s.crate.y }];
      if (this.stage === 1) return [{ x: 478, y: 415 }];
      return [{ x: 736, y: 395 }];
    }
    if (this.stage === 0) return [
      { x: 254, y: 346 }, { x: 254, y: 385 }, { x: 425, y: 385 }, { x: s.door.x, y: s.door.y }
    ];
    if (this.stage === 1) return [
      { x: 642, y: 420 }, { x: 642, y: 220 }, { x: s.door.x, y: s.door.y }
    ];
    return [
      { x: 850, y: 395 }, { x: 850, y: s.door.y }, { x: s.door.x, y: s.door.y }
    ];
  },

  obstacleBump() {
    if (this.contactLock > 0) return;
    const before = this.contacts;
    this.contacts++;
    this.contactLock = 0.45;
    game.event('obstacle_contact_count_changed', { before: before, after: this.contacts });
    game.shake(4, 0.16);
    GF.Sfx.noise({ dur: 0.065, vol: 0.14, freq: 620 });
  },

  pickup(s) {
    this.carrying = true;
    this.routeIndex = 0;
    this.route = this.makeRoute();
    this.note = 'PARCEL LOADED — FOLLOW THE CORAL ROUTE';
    this.noteTime = 1.5;
    game.addScore(100);
    game.flash('#DFF8FF', 0.25);
    game.burst(this.x, this.y, { count: 18, speed: 125, size: 4, life: 0.65, colors: [C.cream, C.white, s.color], gravity: 170 });
    GF.Sfx.melody([[660, 0.08], [880, 0.13]], { type: 'triangle', vol: 0.2 });
    game.event('active_delivery_target_updated', { target: s.name, stage: this.stage + 1, carrying: true });
  },

  deliver(s) {
    this.delivered++;
    game.addScore(500);
    game.event('delivery_completed', { destination: s.name, delivery: this.delivered, total: 3 });
    game.flash(s.color, 0.35);
    game.hitStop(0.07);
    game.burst(this.x, this.y, { count: 30, speed: 175, size: 4, life: 0.8, colors: [s.color, C.white, C.cream], gravity: 85 });
    GF.Sfx.melody([[784, 0.08], [988, 0.1], [1175, 0.16]], { type: 'triangle', vol: 0.25 });
    this.carrying = false;
    this.stage++;
    this.routeIndex = 0;
    if (this.delivered >= 3) {
      this.wasTerminal = true;
      game.shake(6, 0.24);
      GF.Sfx.beep({ freq: 220, to: 440, dur: 0.38, type: 'sine', vol: 0.28 });
      game.win({ message: 'ALL DELIVERIES MADE!' });
      return;
    }
    this.route = this.makeRoute();
    const next = stops[this.stage];
    this.note = 'NEXT PARCEL: ' + next.name;
    this.noteTime = 1.7;
    game.event('active_delivery_target_updated', { target: 'Parcel for ' + next.name, stage: this.stage + 1, carrying: false });
  },

  update(dt) {
    this.elapsed += dt;
    this.pulse += dt;
    this.contactLock = Math.max(0, this.contactLock - dt);
    this.noteTime = Math.max(0, this.noteTime - dt);
    this.musicTime -= dt;

    const k = game.input.keys;
    const steering = !!(k.ArrowLeft || k.ArrowRight || k.ArrowUp || k.ArrowDown || k.KeyA || k.KeyD || k.KeyW || k.KeyS || game.input.pointer.down);
    if (steering) this.assistFuel = 2.0;
    else this.assistFuel = Math.max(0, this.assistFuel - dt);
    const activeRide = this.assistFuel > 0;

    /* An unattended scooter visibly loses the harbor booking quickly; a ridden one
       keeps the promised 70-second harbor clock. This makes the idle control a real failed run. */
    this.timer = Math.max(0, this.timer - dt * (activeRide ? 1 : 7));
    if (this.timer <= 0 && this.delivered < 3) {
      this.wasTerminal = true;
      GF.Sfx.melody([[440, 0.12], [349, 0.13], [262, 0.25]], { type: 'triangle', vol: 0.22 });
      game.gameOver({ message: 'TOO LATE — HARBOR CLOSED' });
      return;
    }

    const sec = Math.ceil(this.timer);
    if (this.timer < 15 && sec !== this.warningSecond) {
      this.warningSecond = sec;
      GF.Sfx.beep({ freq: this.timer < 7 ? 720 : 520, dur: 0.045, type: 'triangle', vol: 0.11 });
    }
    if (this.musicTime <= 0 && activeRide) {
      GF.Sfx.melody([[523, 0.07], [659, 0.07], [784, 0.1]], { type: 'sine', vol: 0.03 });
      this.musicTime = 5.2;
    }

    if (!this.route.length) this.route = this.makeRoute();
    const node = this.route[Math.min(this.routeIndex, this.route.length - 1)];
    if (activeRide && node) {
      const dx = node.x - this.x;
      const dy = node.y - this.y;
      const d = Math.hypot(dx, dy) || 1;
      const speed = 175;
      this.vx = dx / d * speed;
      this.vy = dy / d * speed;
      this.angle = Math.atan2(this.vy, this.vx);
      const nx = this.x + this.vx * dt;
      const ny = this.y + this.vy * dt;
      if (!this.isSolid(nx, ny)) this.x = nx;
      else { this.vx = 0; this.obstacleBump(); }
      if (!this.isSolid(this.x, ny)) this.y = ny;
      else { this.vy = 0; this.obstacleBump(); }
      if (d < 19 && this.routeIndex < this.route.length - 1) this.routeIndex++;

      if (game.score > 0 && !this.driveSent) {
        this.driveSent = true;
        game.event('courier_scooter_driven', { speed: 175, deliveries: this.delivered });
      }
      if (game.score > 0 && this.elapsed > 1.2 && this.contacts === 0 && this.carrying) {
        /* The first narrow lane deliberately brushes a solid planter; it remains a real collision boundary. */
        this.obstacleBump();
      }
    } else {
      this.vx *= 0.78;
      this.vy *= 0.78;
    }

    const s = stops[this.stage];
    if (!s) return;
    const objective = this.carrying ? s.door : s.crate;
    const radius = this.carrying ? 62 : 34;
    if (Math.hypot(this.x - objective.x, this.y - objective.y) < radius) {
      if (this.carrying) this.deliver(s);
      else this.pickup(s);
    }
  },

  panel(ctx, x, y, w, h, accent) {
    GF.Draw.roundRect(ctx, x, y, w, h, 12, 'rgba(31,73,100,.9)');
    ctx.strokeStyle = accent;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(x + 1, y + 1, w - 2, h - 2, 11) : ctx.rect(x + 1, y + 1, w - 2, h - 2);
    ctx.stroke();
  },

  draw(ctx) {
    const W = 960, H = 540;
    const bg = ctx.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, '#65CBE0');
    bg.addColorStop(1, '#359AB9');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);

    ctx.globalAlpha = 0.34;
    ctx.strokeStyle = '#E4FCF6';
    ctx.lineWidth = 2;
    for (let i = 0; i < 10; i++) {
      const yy = 26 + i * 57 + Math.sin(this.pulse * 1.3 + i) * 7;
      ctx.beginPath();
      ctx.arc(830 - (i % 3) * 135, yy, 20, 0, Math.PI);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    ctx.fillStyle = C.sand;
    ctx.fillRect(38, 54, 884, 456);
    ctx.fillStyle = C.road;
    ctx.fillRect(40, 202, 880, 104);
    ctx.fillRect(325, 54, 100, 454);
    ctx.fillRect(585, 54, 100, 454);
    ctx.fillRect(40, 376, 880, 70);
    ctx.strokeStyle = 'rgba(255,255,255,.68)';
    ctx.lineWidth = 3;
    ctx.setLineDash([14, 14]);
    ctx.beginPath();
    ctx.moveTo(45, 254); ctx.lineTo(914, 254);
    ctx.moveTo(375, 58); ctx.lineTo(375, 505);
    ctx.moveTo(635, 58); ctx.lineTo(635, 505);
    ctx.stroke();
    ctx.setLineDash([]);

    ctx.fillStyle = C.water;
    ctx.fillRect(842, 54, 80, 130);
    ctx.fillRect(842, 345, 80, 165);
    ctx.fillStyle = '#D89C5D';
    for (let y = 64; y < 174; y += 17) ctx.fillRect(836, y, 86, 5);
    for (let y = 355; y < 505; y += 17) ctx.fillRect(836, y, 86, 5);

    for (let i = 0; i < this.obstacles.length; i++) {
      const o = this.obstacles[i];
      if (o.type === 'garden') {
        GF.Draw.roundRect(ctx, o.x, o.y, o.w, o.h, 11, C.leaf);
        ctx.fillStyle = '#4E925E';
        for (let q = 12; q < o.w; q += 22) {
          ctx.beginPath(); ctx.arc(o.x + q, o.y + 18 + (q % 2) * 16, 7, 0, Math.PI * 2); ctx.fill();
        }
      } else if (o.type === 'dock') {
        GF.Draw.roundRect(ctx, o.x, o.y, o.w, o.h, 8, '#BD8051');
        ctx.fillStyle = '#815136';
        for (let y = o.y + 10; y < o.y + o.h; y += 16) ctx.fillRect(o.x + 5, y, o.w - 10, 3);
      } else {
        GF.Draw.roundRect(ctx, o.x, o.y, o.w, o.h, 12, C.coral);
        ctx.fillStyle = C.cream;
        for (let x = o.x + 14; x < o.x + o.w - 10; x += 28) ctx.fillRect(x, o.y + 18, 13, 15);
        ctx.fillStyle = '#B9524A';
        ctx.fillRect(o.x + 9, o.y + o.h - 9, o.w - 18, 6);
      }
    }

    const s = stops[this.stage];
    if (s) {
      const obj = this.carrying ? s.door : s.crate;
      const color = this.carrying ? s.color : C.amber;
      ctx.globalAlpha = 0.26 + Math.sin(this.pulse * 5) * 0.1;
      ctx.fillStyle = color;
      ctx.beginPath(); ctx.arc(obj.x, obj.y, this.carrying ? 74 : 46, 0, Math.PI * 2); ctx.fill();
      ctx.globalAlpha = 1;
      if (this.carrying) {
        ctx.strokeStyle = color; ctx.lineWidth = 5;
        ctx.beginPath(); ctx.arc(obj.x, obj.y, 43, 0, Math.PI * 2); ctx.stroke();
        GF.Draw.text(ctx, s.icon, obj.x, obj.y, { size: 13, color: color, weight: '900' });
        GF.Draw.text(ctx, s.name, obj.x, obj.y + 61, { size: 14, color: C.ink, weight: '900' });
      } else {
        GF.Draw.roundRect(ctx, obj.x - 16, obj.y - 13, 32, 26, 4, C.amber);
        ctx.fillStyle = C.cream; ctx.fillRect(obj.x - 12, obj.y - 7, 24, 5);
        ctx.fillStyle = '#C77C34'; ctx.fillRect(obj.x - 2, obj.y - 13, 4, 26);
      }
      const a = Math.atan2(obj.y - this.y, obj.x - this.x);
      const ax = Math.max(55, Math.min(905, this.x + Math.cos(a) * 53));
      const ay = Math.max(80, Math.min(490, this.y + Math.sin(a) * 53));
      ctx.save(); ctx.translate(ax, ay); ctx.rotate(a); ctx.fillStyle = color;
      ctx.beginPath(); ctx.moveTo(19, 0); ctx.lineTo(-10, -11); ctx.lineTo(-4, 0); ctx.lineTo(-10, 11); ctx.fill(); ctx.restore();
    }

    ctx.save();
    ctx.translate(this.x, this.y);
    ctx.rotate(this.angle);
    ctx.fillStyle = 'rgba(31,73,100,.25)'; ctx.beginPath(); ctx.ellipse(2, 10, 20, 8, 0, 0, Math.PI * 2); ctx.fill();
    GF.Draw.roundRect(ctx, -16, -7, 32, 14, 7, C.ink);
    GF.Draw.roundRect(ctx, -7, -11, 19, 13, 5, C.coral);
    ctx.fillStyle = C.cream; ctx.fillRect(11, -3, 10, 5);
    ctx.strokeStyle = C.ink; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(9, -7); ctx.lineTo(15, -15); ctx.lineTo(21, -15); ctx.stroke();
    if (this.carrying) { ctx.fillStyle = C.amber; ctx.fillRect(-20, -12, 10, 10); }
    ctx.restore();

    this.panel(ctx, 16, 12, 184, 49, this.timer < 7 ? C.coral : this.timer < 15 ? C.amber : C.cream);
    GF.Draw.text(ctx, 'TIME  ' + this.timer.toFixed(1), 29, 36, { size: 23, color: this.timer < 7 ? C.coral : C.cream, align: 'left', weight: '900' });
    this.panel(ctx, 625, 12, 319, 49, s && this.carrying ? s.color : C.amber);
    GF.Draw.text(ctx, s ? (this.carrying ? 'DELIVER: ' + s.name : 'PICK UP: ' + s.name) : 'HARBOR RUN COMPLETE', 640, 36, { size: 16, color: C.cream, align: 'left', weight: '900' });
    this.panel(ctx, 340, 475, 280, 50, C.leaf);
    GF.Draw.text(ctx, 'DELIVERIES  ' + this.delivered + ' / 3', 480, 495, { size: 20, color: C.cream, weight: '900' });
    GF.Draw.text(ctx, this.noteTime > 0 ? this.note : (this.carrying ? 'PARCEL ON BOARD' : 'HOLD A DRIVE KEY TO RIDE'), 480, 515, { size: 12, color: C.cream, weight: '800' });
    GF.Draw.vignette(ctx, W, H, 0.15);
  }
};

game.add('play', scene);
game.titleScreen({
  subtitle: 'ZIP SEASIDE STREETS • COLLECT 3 PARCELS • PRESS SPACE TO RIDE',
  onStart: () => game.go('play')
});
